import { deriveTraits } from './traits.js';
self.onmessage = ({ data }) => {
  try {
    const traits = deriveTraits(BigInt(data.baseKey), data.startIndex, data.count, BigInt(data.entropy));
    self.postMessage({ traits }, [traits.buffer]);
  } catch (error) { self.postMessage({ error: error.message }); }
};
